import {
  filePathFor,
  renderFrontmatter,
  srtPathFor,
  wavPathFor,
} from './session/markdown.js';

describe('session export', () => {
  const id = '2026-11-05-session-1026';
  const srt =
    '1\n00:00:02,000 --> 00:00:04,800\nSpeaker 1: Hello.\nXin chào.\n\n' +
    '2\n00:00:05,100 --> 00:00:08,200\nHi there.\n\n';

  // readSession resolves <dir>/<YYYY-MM-DD>/<stem>.md, so the fixture
  // seeds the day subdirectory at the filePathFor/srtPathFor locations.
  async function seedSession() {
    await fs.mkdir(path.dirname(filePathFor(dir, id)), { recursive: true });
    await fs.writeFile(
      filePathFor(dir, id),
      renderFrontmatter({
        id,
        started_at: '2026-11-05T10:26:00.000Z',
        ended_at: '2026-11-05T10:30:00.000Z',
        source_lang: 'en',
        target_lang: 'vi',
        stt_provider: 'deepgram',
        model: 'nova-3',
        diarization: true,
        audio_source: 'mic',
        audio_file: null,
        speakers: {},
        duration_s: 240,
      }),
    );
    await fs.writeFile(srtPathFor(dir, id), srt);
  }

  it('serves the stored .srt as a WebVTT attachment', async () => {
    await seedSession();
    const res = await app.inject({
      method: 'GET',
      url: `/api/sessions/${id}/export?format=vtt`,
    });
    expect(res.statusCode).toBe(200);
    expect(res.headers['content-type']).toContain('text/vtt');
    expect(res.headers['content-disposition']).toBe(
      `attachment; filename="${id}.vtt"`,
    );
    expect(res.body.startsWith('WEBVTT\n')).toBe(true);
    const timingLines = res.body
      .split('\n')
      .filter((l) => l.includes(' --> '));
    expect(timingLines).toHaveLength(2);
    for (const line of timingLines) {
      expect(line).not.toContain(',');
      expect(line).toMatch(
        /^\d{2}:\d{2}:\d{2}\.\d{3} --> \d{2}:\d{2}:\d{2}\.\d{3}$/,
      );
    }
    expect(res.body).toContain('Speaker 1: Hello.');
    expect(res.body).toContain('Xin chào.');
    expect(res.body).toContain('Hi there.');
  });

  it('returns 404 for an unknown session id', async () => {
    const res = await app.inject({
      method: 'GET',
      url: '/api/sessions/2026-11-05-nope-1/export?format=vtt',
    });
    expect(res.statusCode).toBe(404);
  });

  it('returns 400 for a missing or unsupported format', async () => {
    await seedSession();
    for (const url of [
      `/api/sessions/${id}/export`,
      `/api/sessions/${id}/export?format=json`,
    ]) {
      const res = await app.inject({ method: 'GET', url });
      expect(res.statusCode).toBe(400);
      expect((res.json() as { error?: string }).error).toBe(
        'invalid request',
      );
    }
  });
});

